param([string]$ProjectRoot=(Get-Location).Path)

$ErrorActionPreference="Stop"
Set-StrictMode -Version Latest

$ProjectRoot=(Resolve-Path -LiteralPath $ProjectRoot).Path
$State=Join-Path $ProjectRoot "PROJECT_STATE"
$Audit=Join-Path $ProjectRoot "audit_exports"
$Milestones=Join-Path $State "milestones"
$PackageDir=Join-Path $State "guarded_250_symbol_progressive_canary_package_v1"
New-Item -ItemType Directory -Force -Path $State,$Audit,$Milestones,$PackageDir|Out-Null

$stamp=Get-Date -Format "yyyyMMdd_HHmmss"
$manifestFile=Join-Path $PackageDir "manifest.json"
$executionFile=Join-Path $PackageDir "execute_250_symbol_progressive_canary.sh"
$rollbackFile=Join-Path $PackageDir "rollback_to_core25.sh"
$report=Join-Path $Audit "S10_7D_250_SYMBOL_PROGRESSIVE_PACKAGE_report_$stamp.txt"
$raw=Join-Path $Audit "S10_7D_250_SYMBOL_PROGRESSIVE_PACKAGE_raw_$stamp.json"
$milestone=Join-Path $Milestones "S10_7D_250_SYMBOL_PROGRESSIVE_PACKAGE_$stamp.md"

[IO.File]::WriteAllBytes($executionFile,[Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($rollbackFile,[Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($manifestFile,[Convert]::FromBase64String(""))

$result=[ordered]@{
 ok=$true
 classification="DAY7D_GUARDED_250_SYMBOL_PROGRESSIVE_CANARY_PACKAGE_VALIDATED"
 packageBuilt=$true
 packageExecuted=$false
 executionAuthorized=$false
 currentVerifiedCapacity=25
 targetCapacity=250
 rampStages=@(50,100,150,250)
 stageMicroSoakMinutes=5
 finalSoakMinutes=30
 rollbackTarget="Core25"
 productionMutation=$false
 serviceRestarted=$false
 systemdTouched=$false
 streamSymbolsChanged=$false
 validationErrors=@()
 nextAction="REVIEW_AND_ARM_250_SYMBOL_PROGRESSIVE_CANARY"
 packageDirectory=$PackageDir
}

$result|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $raw -Encoding UTF8

@(
"S10.7D GUARDED 250-SYMBOL PROGRESSIVE CANARY PACKAGE",
"Generated=$stamp",
"OK=True",
"CLASSIFICATION=DAY7D_GUARDED_250_SYMBOL_PROGRESSIVE_CANARY_PACKAGE_VALIDATED",
"PACKAGE_BUILT=True",
"PACKAGE_EXECUTED=False",
"EXECUTION_AUTHORIZED=False",
"CURRENT_VERIFIED_CAPACITY=25",
"TARGET_CAPACITY=250",
"RAMP_STAGES=50->100->150->250",
"STAGE_MICRO_SOAK_MINUTES=5",
"FINAL_SOAK_MINUTES=30",
"ROLLBACK_TARGET=Core25",
"PRODUCTION_MUTATION=False",
"SERVICE_RESTARTED=False",
"SYSTEMD_TOUCHED=False",
"STREAM_SYMBOLS_CHANGED=False",
"NEXT_ACTION=REVIEW_AND_ARM_250_SYMBOL_PROGRESSIVE_CANARY",
"PACKAGE_DIR=$PackageDir",
"RAW_JSON=$raw"
)|Set-Content -LiteralPath $report -Encoding UTF8

@"
# S10.7D Guarded 250-Symbol Progressive Canary Package

- Built: True
- Executed: False
- Authorized: False
- Ramp: 25 → 50 → 100 → 150 → 250
- Micro-soak: 5 minutes per stage
- Final soak: 30 minutes
- Rollback target: Core25
- Next: REVIEW_AND_ARM_250_SYMBOL_PROGRESSIVE_CANARY

No production mutation.
"@|Set-Content -LiteralPath $milestone -Encoding UTF8

Write-Host ""
Write-Host "=== S10.7D GUARDED 250-SYMBOL PACKAGE COMPLETE ===" -ForegroundColor Green
Write-Host "OK: True"
Write-Host "Classification: DAY7D_GUARDED_250_SYMBOL_PROGRESSIVE_CANARY_PACKAGE_VALIDATED"
Write-Host "Package built: True"
Write-Host "Package executed: False"
Write-Host "Execution authorized: False"
Write-Host "Current verified capacity: 25"
Write-Host "Target capacity: 250"
Write-Host "Ramp stages: 50 -> 100 -> 150 -> 250"
Write-Host "Micro-soak per stage: 5 minutes"
Write-Host "Final soak: 30 minutes"
Write-Host "Rollback target: Core25"
Write-Host "Next action: REVIEW_AND_ARM_250_SYMBOL_PROGRESSIVE_CANARY"
Write-Host "Package directory: $PackageDir"
Write-Host "Report: $report"
Write-Host "Raw: $raw"
Write-Host "Milestone: $milestone"
